// Arduino가 기대하는 형식: "pump=1 fan=128"
// switch/slider가 각각 들어올 수 있어 마지막 값을 context에 저장해서 합칩니다.

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

const pump = (msg._ui && msg._ui.type === 'switch') ? msg.payload : flow.get('pump');
const fan  = (msg._ui && msg._ui.type === 'slider') ? msg.payload : flow.get('fan');

if (msg._ui && msg._ui.type === 'switch') flow.set('pump', pump);
if (msg._ui && msg._ui.type === 'slider') flow.set('fan', fan);

const p = (pump === undefined) ? (flow.get('pump') ?? '0') : pump;
const f = (fan === undefined)  ? (flow.get('fan')  ?? '0') : fan;

msg.topic = `cronusfarm/${devId}/cmd`;
msg.payload = `pump=${p} fan=${f}`;
return msg;

msg.payload = (msg.payload || '').toString().trim();
if (!msg.payload) return null;
return msg;

// MQTT tele → InfluxDB 2.x Line Protocol (측정값만, 토큰은 환경변수)
// 채널·펌프가드(G:)·fan·pump_c/d 포함
// 필요: CRONUSFARM_INFLUX_TOKEN, 선택: CRONUSFARM_INFLUX_ORG, CRONUSFARM_INFLUX_BUCKET, CRONUSFARM_INFLUX_MIN_MS

const token = (env.get('CRONUSFARM_INFLUX_TOKEN') || '').toString().trim();
if (!token) {
  if (!flow.get('_influxWarned')) {
    flow.set('_influxWarned', true);
    node.warn('Influx: CRONUSFARM_INFLUX_TOKEN 없음 → 기록 생략');
  }
  return null;
}

const minMs = parseInt((env.get('CRONUSFARM_INFLUX_MIN_MS') || '5000').toString(), 10) || 5000;
const now = Date.now();
const last = flow.get('lastInfluxWriteMs') || 0;
if (now - last < minMs) return null;
flow.set('lastInfluxWriteMs', now);

const s = (msg.payload || '').toString();
if (!s.trim()) return null;

function parseKV(part) {
  const out = {};
  (part || '').trim().split(/\s+/).forEach(tok => {
    const m = tok.match(/^([^=]+)=(.+)$/);
    if (!m) return;
    out[m[1]] = m[2];
  });
  return out;
}

const ps = s.split('|').map(x => x.trim());
const pS = ps.find(x => x.startsWith('S:'));
const pA = ps.find(x => x.startsWith('A:'));
const pT = ps.find(x => x.startsWith('T:'));
const kvS = parseKV(pS ? pS.slice(2) : '');
const kvA = parseKV(pA ? pA.slice(2) : '');
const kvT = parseKV(pT ? pT.slice(2) : '');
const pG = ps.find(x => x.startsWith('G:'));
let guard_ok = 1, guard_mx = 0, guard_mf = 0;
if (pG) {
  const gr = pG.slice(2).trim();
  if (gr && gr !== 'ok') {
    guard_ok = 0;
    gr.split(/\s+/).forEach(tok => {
      if (tok.indexOf('=mx') >= 0) guard_mx = 1;
      if (tok.indexOf('=mf') >= 0) guard_mf = 1;
    });
  }
}

const parts = (msg.topic || '').toString().split('/').filter(Boolean);
const deviceId = (parts.length >= 2 ? parts[1] : 'cronusfarm-01').replace(/[^a-zA-Z0-9_-]/g, '_');

const fields = [];
const ch = ['led_a1', 'led_a2', 'led_b1', 'pump_a1', 'pump_a2', 'pump_b1', 'pump_b2', 'fan_a1', 'fan_a2', 'fan_b1', 'fan_b2', 'pump_c1', 'pump_c2', 'pump_d1', 'pump_d2'];
ch.forEach(k => {
  if (kvS[k] === undefined) return;
  fields.push(`${k}=${kvS[k] === '1' ? 1 : 0}i`);
});
ch.forEach(k => {
  if (kvA[k] === undefined) return;
  fields.push(`auto_${k}=${kvA[k] === '1' ? 1 : 0}i`);
});
Object.keys(kvT).forEach(k => {
  const m = (kvT[k] || '').toString().match(/^(\d+)\/(\d+)$/);
  if (!m) return;
  fields.push(`${k}_on_s=${parseInt(m[1], 10)}i`);
  fields.push(`${k}_off_s=${parseInt(m[2], 10)}i`);
});
fields.push(`guard_ok=${guard_ok}i`);
fields.push(`guard_mx=${guard_mx}i`);
fields.push(`guard_mf=${guard_mf}i`);

const org = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_ORG') || 'cronusfarm').toString()));
const bucket = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_BUCKET') || 'cronusfarm').toString()));
const base = ((env.get('CRONUSFARM_INFLUX_URL') || 'http://127.0.0.1:8086/api/v2/write').toString()).replace(/\/$/, '');

msg.method = 'POST';
msg.url = `${base}?org=${org}&bucket=${bucket}&precision=ns`;
msg.headers = {
  Authorization: `Token ${token}`,
  'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = `tele,device_id=${deviceId} ${fields.join(',')} ${now * 1e6}`;
return msg;

// 알림/이벤트(JSON) → InfluxDB (measurement: alert_events)
// bucket은 환경변수 CRONUSFARM_INFLUX_BUCKET(권장: CronusFarm)을 사용합니다.

const token = (env.get('CRONUSFARM_INFLUX_TOKEN') || '').toString().trim();
if (!token) return null;

const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};

function escTag(v) {
  return (v ?? '').toString().replace(/[,=\s]/g, '_');
}
function escStr(v) {
  return (v ?? '').toString().replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}
function numOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

const now = Date.now();
const org = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_ORG') || 'cronusfarm').toString()));
const bucket = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_BUCKET') || 'CronusFarm').toString()));
const base = ((env.get('CRONUSFARM_INFLUX_URL') || 'http://127.0.0.1:8086/api/v2/write').toString()).replace(/\/$/, '');

const tags = [`source=${escTag(p.source || 'unknown')}`];
if (p.zone) tags.push(`zone=${escTag(p.zone)}`);
if (p.alert_type) tags.push(`alert_type=${escTag(p.alert_type)}`);

const fields = [];
if (p.severity !== undefined) fields.push(`severity=\"${escStr(p.severity)}\"`);
if (p.message !== undefined) fields.push(`message=\"${escStr(p.message)}\"`);

const va = numOrNull(p.value_actual);
if (va !== null) fields.push(`value_actual=${va}`);
const vt = numOrNull(p.value_threshold);
if (vt !== null) fields.push(`value_threshold=${vt}`);

if (!fields.length) return null;

msg.method = 'POST';
msg.url = `${base}?org=${org}&bucket=${bucket}&precision=ns`;
msg.headers = { Authorization: `Token ${token}`, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = `alert_events,${tags.join(',')} ${fields.join(',')} ${now * 1e6}`;
return msg;

// AI 감지(JSON) → InfluxDB (measurement: ai_detections)

const token = (env.get('CRONUSFARM_INFLUX_TOKEN') || '').toString().trim();
if (!token) return null;

const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};

function escTag(v) {
  return (v ?? '').toString().replace(/[,=\s]/g, '_');
}
function escStr(v) {
  return (v ?? '').toString().replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}
function numOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

const now = Date.now();
const org = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_ORG') || 'cronusfarm').toString()));
const bucket = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_BUCKET') || 'CronusFarm').toString()));
const base = ((env.get('CRONUSFARM_INFLUX_URL') || 'http://127.0.0.1:8086/api/v2/write').toString()).replace(/\/$/, '');

const tags = [];
if (p.zone) tags.push(`zone=${escTag(p.zone)}`);
if (p.camera) tags.push(`camera=${escTag(p.camera)}`);
if (p.detection_type) tags.push(`detection_type=${escTag(p.detection_type)}`);
if (p.label) tags.push(`label=${escTag(p.label)}`);

const fields = [];
const conf = numOrNull(p.confidence);
if (conf !== null) fields.push(`confidence=${conf}`);
if (p.severity !== undefined) fields.push(`severity=\"${escStr(p.severity)}\"`);
if (p.model_name !== undefined) fields.push(`model_name=\"${escStr(p.model_name)}\"`);
if (p.model_version !== undefined) fields.push(`model_version=\"${escStr(p.model_version)}\"`);
if (p.is_confirmed !== undefined) fields.push(`is_confirmed=${(p.is_confirmed ? 1 : 0)}i`);

if (!fields.length) return null;

msg.method = 'POST';
msg.url = `${base}?org=${org}&bucket=${bucket}&precision=ns`;
msg.headers = { Authorization: `Token ${token}`, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = `ai_detections${tags.length ? ',' + tags.join(',') : ''} ${fields.join(',')} ${now * 1e6}`;
return msg;

// 기상청 초단기실황(getUltraSrtNcst) → JSON
// env:
// - CRONUSFARM_KMA_SERVICE_KEY : 디코딩된 서비스키(= 포함 원문) 권장
// - CRONUSFARM_KMA_NX / CRONUSFARM_KMA_NY : 격자 좌표
// 주의: KMA는 KST(UTC+9) 기준 base_date/base_time을 사용합니다.

const key = (env.get('CRONUSFARM_KMA_SERVICE_KEY') || '').toString().trim();
const nx = parseInt((env.get('CRONUSFARM_KMA_NX') || '0').toString(), 10) || 0;
const ny = parseInt((env.get('CRONUSFARM_KMA_NY') || '0').toString(), 10) || 0;
if (!key || !nx || !ny) {
  node.warn('KMA: SERVICE_KEY 또는 NX/NY 누락 → 수집 생략');
  return null;
}

function pad2(n) { return (n < 10 ? '0' : '') + n; }

// KST now
const nowUtc = new Date();
const nowKstMs = nowUtc.getTime() + (9 * 60 * 60 * 1000);
const nowKst = new Date(nowKstMs);

let y = nowKst.getUTCFullYear();
let mo = nowKst.getUTCMonth() + 1;
let d = nowKst.getUTCDate();
let hh = nowKst.getUTCHours();
let mm = nowKst.getUTCMinutes();

// 발표 시각 여유: 매 시각 40분 이후에 해당 시간 데이터가 안정적으로 조회되는 경우가 많아
// 40분 이전이면 이전 시간(정시)로 물립니다.
if (mm < 40) {
  hh -= 1;
  if (hh < 0) {
    hh = 23;
    const prev = new Date(nowKstMs - 24 * 60 * 60 * 1000);
    y = prev.getUTCFullYear();
    mo = prev.getUTCMonth() + 1;
    d = prev.getUTCDate();
  }
}

const base_date = `${y}${pad2(mo)}${pad2(d)}`;
const base_time = `${pad2(hh)}00`;

const qs = new URLSearchParams({
  serviceKey: key,
  numOfRows: '60',
  pageNo: '1',
  dataType: 'JSON',
  base_date,
  base_time,
  nx: String(nx),
  ny: String(ny)
});

msg.method = 'GET';
msg.url = `https://apis.data.go.kr/1360000/VilageFcstInfoService_2.0/getUltraSrtNcst?${qs.toString()}`;
msg.headers = { 'User-Agent': 'CronusFarm/NodeRED' };
msg.kma = { base_date, base_time, nx, ny };
return msg;

// KMA 응답(JSON) → Influx write + MQTT 스냅샷(/ui Farm 환경)
// 출력1: Influx(토큰 있을 때만) · 출력2: cronusfarm/kma/snapshot(retain)

const token = (env.get('CRONUSFARM_INFLUX_TOKEN') || '').toString().trim();

function numOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

if (typeof msg.payload === 'string') {
  const raw = msg.payload;
  try {
    msg.payload = JSON.parse(raw);
  } catch (e) {
    node.warn('KMA: JSON 파싱 실패(응답 일부): ' + raw.slice(0, 200));
    return null;
  }
}

const body = msg.payload;
const items = body?.response?.body?.items?.item;
if (!Array.isArray(items)) {
  node.warn('KMA: items 없음/형식 불일치');
  return null;
}

const m = {};
for (const it of items) {
  const cat = (it?.category || '').toString();
  const val = (it?.obsrValue ?? '').toString();
  if (!cat) continue;
  m[cat] = val;
}

const temp = numOrNull(m.T1H);
const reh = numOrNull(m.REH);
const vec = numOrNull(m.VEC);
const wsd = numOrNull(m.WSD);
const pty = numOrNull(m.PTY);

const fields = [];
if (temp !== null) fields.push(`kma_temp=${temp}`);
if (reh !== null) fields.push(`kma_humidity=${reh}`);
if (vec !== null) fields.push(`kma_wind_dir=${vec}`);
if (wsd !== null) fields.push(`kma_wind_speed=${wsd}`);
if (pty !== null) fields.push(`kma_pty=${pty}i`);

const now = Date.now();
const org = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_ORG') || 'cronusfarm').toString()));
const bucket = encodeURIComponent(((env.get('CRONUSFARM_INFLUX_BUCKET') || 'CronusFarm').toString()));
const base = ((env.get('CRONUSFARM_INFLUX_URL') || 'http://127.0.0.1:8086/api/v2/write').toString()).replace(/\/$/, '');
const nx = msg.kma?.nx;
const ny = msg.kma?.ny;
const tags = [`source=kma`];
if (nx && ny) tags.push(`nx=${nx}`, `ny=${ny}`);

const snap = {
  kma_temp: temp,
  kma_humidity: reh,
  kma_wind_dir: vec,
  kma_wind_speed: wsd,
  kma_pty: pty,
  base_date: msg.kma?.base_date,
  base_time: msg.kma?.base_time,
  nx,
  ny,
  ts: now
};

const uiMsg = {
  topic: 'cronusfarm/kma/snapshot',
  qos: 0,
  retain: true,
  payload: JSON.stringify(snap)
};

let influxMsg = null;
if (token && fields.length) {
  influxMsg = {
    method: 'POST',
    url: `${base}?org=${org}&bucket=${bucket}&precision=ns`,
    headers: { Authorization: `Token ${token}`, 'Content-Type': 'text/plain; charset=utf-8' },
    payload: `tele,${tags.join(',')} ${fields.join(',')} ${now * 1e6}`
  };
}

return [ influxMsg, uiMsg ];

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
const minMs = parseInt((env.get('CRONUSFARM_SQLITE_MIN_MS') || '15000').toString(), 10) || 15000;
const now = Date.now();
const last = flow.get('lastSqliteTeleMs') || 0;
if (now - last < minMs) return null;
flow.set('lastSqliteTeleMs', now);
const parts = (msg.topic || '').toString().split('/').filter(Boolean);
const deviceId = (parts.length >= 2 ? parts[1] : 'cronusfarm-01');
msg.method = 'POST';
msg.url = base + '/ingest/tele';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: deviceId,
  topic: msg.topic,
  raw: (msg.payload || '').toString(),
  ts_ms: now
});
return msg;

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
const parts = (msg.topic || '').toString().split('/').filter(Boolean);
const deviceId = (parts.length >= 2 ? parts[1] : 'cronusfarm-01');
const now = Date.now();
msg.method = 'POST';
msg.url = base + '/ingest/cmd';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: deviceId,
  topic: msg.topic,
  payload: (msg.payload || '').toString(),
  ts_ms: now
});
return msg;

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
const minMs = parseInt((env.get('CRONUSFARM_SQLITE_STATUS_MIN_MS') || '60000').toString(), 10) || 60000;
const now = Date.now();
const last = flow.get('lastSqliteStatusMs') || 0;
if (now - last < minMs) return null;
flow.set('lastSqliteStatusMs', now);
const parts = (msg.topic || '').toString().split('/').filter(Boolean);
const deviceId = (parts.length >= 2 ? parts[1] : 'cronusfarm-01');
msg.method = 'POST';
msg.url = base + '/ingest/status';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: deviceId,
  topic: msg.topic,
  payload: (msg.payload || '').toString(),
  ts_ms: now
});
return msg;

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const devId = flow.get('deviceId') || 'cronusfarm-01';
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
let key = (msg.topic || '').toString().trim();
if (!key && msg.properties && msg.properties.topic) key = String(msg.properties.topic).trim();
if (!key) {
  node.warn('KV: topic 없음 — Change 노드·슬라이더 설정 확인');
  return null;
}
msg.method = 'POST';
msg.url = base + '/settings/kv';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: devId,
  key,
  value: String(msg.payload)
});
return msg;

const d = new Date();
msg.payload = d.toLocaleString('ko-KR', { hour12: false });
return msg;

const s = (msg.payload || '').toString();
const parts = s.split('|').map(x => x.trim());
const w = parts.find(x => x.startsWith('W:'));
let ssid = '-';
let ip = '-';
if (w) {
  const rest = w.slice(2).trim();
  const k = rest.lastIndexOf(' ip=');
  if (k >= 0 && rest.startsWith('ssid=')) {
    ssid = rest.slice(5, k).trim();
    ip = rest.slice(k + 4).trim();
    if (!ssid) ssid = '-';
    if (!ip) ip = '-';
    if (ip === '0.0.0.0') ip = '-';
  }
}
return [[{ payload: ssid }], [{ payload: ip }]];

const s=(msg.payload||'').toString().trim();
msg.payload = (s.split(/\s+/)[0]||'-');
return msg;

const s=(msg.payload||'').toString().trim();
msg._ok = (s==='active');
msg.payload = msg._ok ? 'online' : 'offline';
return msg;

const s=(msg.payload||'').toString().trim();
msg._ok = (s==='active');
msg.payload = msg._ok ? 'online' : 'offline';
return msg;

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
else if (p != null && typeof p !== 'string') p = String(p);
flow.set('arduinoLastTeleMs', Date.now());
flow.set('lastTeleStr', (p || '').toString());
msg.payload = p;
return msg;

// 문자열 payload만 (§2.2). G: 는 끝 구간 — SSID에 '|' 가 있으면 split('|') 실패 → 정규식 추출
const s = (flow.get('lastTeleStr') || '').toString();
let line = '— (tele 수신 대기)';
if (s.trim().length) {
  let raw = '';
  const m = s.match(/\|\s*G:\s*(.+)$/);
  if (m && m[1] !== undefined) {
    raw = m[1].trim();
  }
  if (!raw.length) {
    const ps = s.split('|').map(x => String(x).trim());
    const pG = ps.find(x => /^g:/i.test(x));
    if (pG) raw = pG.replace(/^g:\s*/i, '').trim();
  }
  if (!raw.length) {
    line = '— (G: 없음 — R4에 최신 스케치 업로드 또는 tele 끝에 | G:… 없음)';
    flow.set('lastTeleG', '');
    flow.set('lastTeleGWarn', false);
  } else {
    line = raw;
    flow.set('lastTeleG', line);
    flow.set('lastTeleGWarn', line !== 'ok');
  }
} else {
  flow.set('lastTeleG', '');
  flow.set('lastTeleGWarn', false);
}
msg.payload = line;
return msg;

const now=Date.now();
const ls=flow.get('arduinoLastStatusMs')||0;
const lt=flow.get('arduinoLastTeleMs')||0;
const STATUS_MS=35000;
const TELE_MS=12000;
const ok=((now-ls)<STATUS_MS)||((now-lt)<TELE_MS);
msg._ok=ok;
msg.statusAge=ls?Math.floor((now-ls)/1000):null;
msg.teleAge=lt?Math.floor((now-lt)/1000):null;
const pl=msg.payload;
let raw='';
if(typeof pl==='string'&&pl.length){ raw=pl; }
else { raw=(flow.get('lastTeleStr')||'').toString(); }
msg.telePreview = raw;
msg.payload = raw;
return msg;

// tele 예)
// S:led_a1=0 ... pump_b2=1 fan_a1=1 | A:led_a1=0 ... auto_fan_a1=0 | T:pump_a1=30/90 ...
//
// 중요: tele이 1초마다 오기 때문에, UI 드롭다운(dd_*)을 매번 덮어쓰면 "시간이 계속 바뀌는" 것처럼 보일 수 있습니다.
// 여기서는 on_/off_ 초 값만 반영하고(dd_ 분/초 UI 갱신은 하지 않음), 드롭다운은 사용자가 바꾼 값이 유지되도록 합니다.

const s=(msg.payload||'').toString();
function parseKV(part){
  const out={};
  (part||'').trim().split(/\s+/).forEach(tok=>{
    const m=tok.match(/^([^=]+)=(.+)$/);
    if(!m) return;
    out[m[1]] = m[2];
  });
  return out;
}

const ps = s.split('|').map(x=>x.trim());
const pS = ps.find(x=>x.startsWith('S:'));
const pA = ps.find(x=>x.startsWith('A:'));
const pT = ps.find(x=>x.startsWith('T:'));

const kvS = parseKV(pS ? pS.slice(2) : '');
const kvA = parseKV(pA ? pA.slice(2) : '');
const kvT = parseKV(pT ? pT.slice(2) : '');

const chKeys = ['led_a1','led_a2','pump_a1','pump_a2','led_b1','pump_b1','pump_b2','fan_a1','fan_a2','fan_b1','fan_b2','pump_c1','pump_c2','pump_d1','pump_d2'];

const out=[];
chKeys.forEach(k=>{
  if(k in kvS) {
    const v = (kvS[k]==='1')?1:0;
    flow.set(k, v);
    out.push({topic:k, payload: v});
  }
});
chKeys.forEach(k=>{
  const ak = 'auto_'+k;
  if(k in kvA) {
    const v = (kvA[k]==='1')?1:0;
    flow.set(ak, v);
    out.push({topic:ak, payload: v});
  }
});

Object.keys(kvT).forEach(k=>{
  // pump_x=30/90
  const m = (kvT[k]||'').match(/^(\d+)\/(\d+)$/);
  if(!m) return;
  const onV = parseInt(m[1],10);
  const offV = parseInt(m[2],10);
  const onK = 'on_'+k;
  const offK = 'off_'+k;
  flow.set(onK, onV);
  flow.set(offK, offV);
  out.push({topic:onK, payload: onV});
  out.push({topic:offK, payload: offV});
});

return [out];

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

const k = (msg.topic||'').toString().trim();
if(!k) return null;
const v = (msg.payload===1 || msg.payload===true || msg.payload==='1' || msg.payload==='on') ? 1 : 0;

// 스위치 조작 시: 해당 채널을 수동(auto=0)으로 고정하고, 즉시 ON/OFF 값을 cmd로 발행
// - 출력 1개에서 연속 두 MQTT 메시지: [m1, m2] 반환. [[m1,m2]]는 잘못된 형태입니다.
const t = `cronusfarm/${devId}/cmd`;
const m1 = {topic:t, payload:`auto_${k}=0`};
const m2 = {topic:t, payload:`${k}=${v}`};
return [m1, m2];

const key = (msg.topic || '').toString();
const v = Number(msg.payload);
if (!key) return null;
flow.set(key, isNaN(v) ? 0 : v);
const mm = key.match(/^dd_(on|off)_(pump_[a-z0-9]+)_(m|s)$/);
if (!mm) return null;
const kind = mm[1];
const pk = mm[2];
const minutes = Number(flow.get('dd_' + kind + '_' + pk + '_m')) || 0;
const seconds = Number(flow.get('dd_' + kind + '_' + pk + '_s')) || 0;
let t = minutes * 60 + seconds;
if (t < 1) t = 1;
if (t > 3600) t = 3600;
const outTopic = kind + '_' + pk;
flow.set(outTopic, t);
msg.topic = outTopic;
msg.payload = t;
return msg;

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

const key = (msg.topic||'').toString();
const val = msg.payload;
if (key) flow.set(key, val);

const keys = [
  'led_a1','led_a2','pump_a1','pump_a2','led_b1','pump_b1','pump_b2',
  'auto_led_a1','auto_led_a2','auto_pump_a1','auto_pump_a2','auto_led_b1','auto_pump_b1','auto_pump_b2',
  'on_pump_a1','off_pump_a1','on_pump_a2','off_pump_a2','on_pump_b1','off_pump_b1','on_pump_b2','off_pump_b2'
];

const parts=[];
keys.forEach(k=>{
  const v = flow.get(k);
  if (v === undefined || v === null) return;
  parts.push(`${k}=${v}`);
});

msg.topic = `cronusfarm/${devId}/cmd`;
msg.payload = parts.join(' ');
return msg;

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

// FlexDash 위젯마다 topic이 다르게 들어올 수 있어 방어적으로 처리
const candidates = [
  msg.topic,
  msg.fd_output_topic,
  msg.fdOutputTopic,
  msg?._fd?.output_topic,
  msg?._fd?.outputTopic,
  msg?.widget?.topic
];
const k = (candidates.find(x => (x ?? '').toString().trim().length > 0) ?? '').toString().trim();
if(!k) return null;

// FlexDash toggle payload는 기본 true/false 또는 1/0
const v = (msg.payload===1 || msg.payload===true || msg.payload==='1' || msg.payload==='on') ? 1 : 0;

const t = `cronusfarm/${devId}/cmd`;
const m1 = {topic:t, payload:`auto_${k}=0`};
const m2 = {topic:t, payload:`${k}=${v}`};
return [m1, m2];
